    code: "REPO=123456789012.dkr.ecr.us-east-1.amazonaws.com/fastapi-app\n\naws ecr create-repository --repository-name fastapi-app \\\n    --image-scanning-configuration scanOnPush=true \\\n    --image-tag-mutability IMMUTABLE\n\naws ecr get-login-password --region us-east-1 \\\n    | docker login --username AWS --password-stdin 123456789012.dkr.ecr.us-east-1.amazonaws.com\n\ndocker build -t fastapi-app:1.4.0 .\ndocker tag fastapi-app:1.4.0 $REPO:1.4.0\ndocker push $REPO:1.4.0",
